from pathlib import Path
import json, html, shutil
P=Path(__file__).parent; D=P/'dist'; D.mkdir(exist_ok=True); (D/'guides').mkdir(exist_ok=True)
guides=json.loads((P/'content/guides.json').read_text()); e=html.escape

def shell(title,body,sub=False):
 r='../' if sub else './'
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="An unofficial NTHU student survival guide: practical checklists, campus life, and official university resources."><title>{e(title)} · NTHU Fieldnotes</title><link rel="stylesheet" href="{r}assets/style.css"><script defer src="{r}assets/app.js"></script></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="{r}index.html"><span class="brand-mark">N<span>↗</span></span><span>NTHU <b>fieldnotes</b><small>THE STUDENT SURVIVAL GUIDE</small></span></a><nav aria-label="Main navigation"><a href="{r}index.html#guides">Explore guides</a><a href="{r}index.html#checklist">First-week checklist</a><a href="{r}index.html#resources">Official links ↗</a></nav></header><main id="main">{body}</main><footer><a class="footer-brand" href="{r}index.html">NTHU fieldnotes ↗</a><p>A little less lost. A little more at home.</p><div>Independent student project · Not an official NTHU website.<br>Check official sources for current requirements, hours, and schedules.</div><a href="{r}AGENTS.md">Read the project’s AGENTS.md ↗</a></footer></body></html>'''

art='''<svg viewBox="0 0 560 380" role="img" aria-labelledby="campus-title"><title id="campus-title">A playful illustration of campus buildings and trees, not a campus map</title><circle cx="422" cy="82" r="45" fill="#f2b969"/><path d="M5 300 Q120 205 268 280 T560 250 V380 H0" fill="#cdd3b0"/><path d="M0 345 Q130 275 270 310 T560 310 V380 H0" fill="#b1b99a"/><path d="M245 380 Q400 294 355 249" stroke="#f7edda" stroke-width="43" fill="none"/><g stroke="#294c41" stroke-width="3"><path d="M125 170 L280 135 409 170 252 210Z" fill="#385d4d"/><path d="M140 184 V285 L252 321 V210Z" fill="#e6dfc8"/><path d="M252 210 L392 177 V280 L252 321Z" fill="#f8f0df"/><path d="M165 209 V272 M191 217 V281 M218 224 V290" stroke-width="11"/><path d="M275 225 L372 201 M275 250 L372 226 M275 275 L372 251" stroke-width="12"/><path d="M235 165 V118 L275 108 V150" fill="#f8f0df"/><path d="M224 119 L255 98 286 108 255 131Z" fill="#385d4d"/></g><g fill="#52715a"><ellipse cx="95" cy="222" rx="28" ry="50"/><ellipse cx="432" cy="255" rx="29" ry="48"/><ellipse cx="475" cy="281" rx="22" ry="39"/><ellipse cx="66" cy="282" rx="21" ry="38"/></g><g stroke="#294c41" stroke-width="4"><path d="M95 218 V299 M432 250 V328 M475 277 V341 M66 280 V331"/></g><path d="M31 122q12-13 24 0m24-24q12-13 24 0" fill="none" stroke="#385d4d" stroke-width="2"/></svg>'''
cards=''.join(f'''<a class="guide-card" href="guides/{g['slug']}.html" data-category="{g['category']}" data-search="{e(g['short']+' '+g['summary']+' '+g['category'])}"><div class="card-top"><span class="number">{g['icon']}</span><span class="tag">{g['category']}</span></div><h3>{e(g['short'])}<span>↗</span></h3><p>{e(g['summary'])}</p><div class="card-bottom">READ THE GUIDE <span>→</span></div></a>''' for g in guides)
first=['Read my department’s new-student instructions','Check course selection dates and my timetable','Find my classrooms and check the campus','Bookmark current shuttle and library information','Save the university contacts relevant to me','Choose one campus activity to explore']
def checks(items,prefix):return ''.join(f'<label class="check"><input type="checkbox" data-save="{prefix}-{i}"><span>{e(t)}</span></label>' for i,t in enumerate(items))
body=f'''<section class="hero"><div><div class="eyebrow"><span class="dot"></span> HSINCHU, TAIWAN · 國立清華大學</div><h1>New to NTHU?<br>Find your <em>footing.</em></h1><p class="hero-copy">From your first timetable to your favorite study spot. A practical little guide to making campus life feel like yours.</p><a class="button" href="#guides">Find your next step <span>↗</span></a><p class="hero-note">Made for students. Especially the slightly overwhelmed ones.</p></div><div class="hero-art"><span class="art-label">YOUR NEXT CHAPTER STARTS HERE</span>{art}<div class="art-caption"><span>清華生活筆記</span><span>Campus life, one step at a time.</span></div></div></section><div class="ribbon"><span>A guide for your everyday campus questions</span><span>{len(guides)} practical guides</span><span>Official resources, one click away ↗</span></div><section class="explore section" id="guides"><div class="section-heading"><div class="eyebrow">01 / GET YOUR BEARINGS</div><h2>A little guidance.<br>A lot more confidence.</h2><p>Pick what’s on your mind. Start wherever you are.</p></div><div class="tools"><div class="filters" role="group" aria-label="Filter guides">{''.join(f'<button data-filter="{c}" aria-pressed="{str(c=="All guides").lower()}">{c}</button>' for c in ['All guides','Academics','Campus life','Daily essentials'])}</div><label class="search"><span aria-hidden="true">⌕</span><input type="search" id="search" aria-label="Search guides" placeholder="Search the guide…"></label></div><p class="sr-only" id="result-count" role="status" aria-live="polite">{len(guides)} guides</p><div class="cards">{cards}</div><p id="empty" hidden>No guides found. Try “course”, “dorm”, or another category.</p></section><section class="checklist-section section" id="checklist"><div><div class="eyebrow">02 / ONE THING AT A TIME</div><h2>Your first week,<br><em>made manageable.</em></h2><p>You don’t have to figure everything out today.<br>Start with these small wins.</p><div class="progress-label"><strong id="progress-text">0 of 6 complete</strong><span>YOU’VE GOT THIS ↗</span></div><progress id="progress" value="0" max="6">0 of 6</progress><p class="small">Saved only in this browser. No account needed.</p><button class="reset" id="reset-checklist">Reset checklist</button><span id="save-status" class="small" role="status"></span></div><div class="checklist">{checks(first,'first-week')}</div></section><section class="section resources" id="resources"><div class="eyebrow">03 / GO TO THE SOURCE</div><h2>The official starting points.</h2><p>For the latest rules and notices, these are the places to check.</p><div class="resource-grid">{''.join(f'<a href="{url}" target="_blank" rel="noopener noreferrer"><span>{name}<small>{desc}</small></span><b>↗</b></a>' for name,desc,url in [('Curriculum Division','Course selection & enrollment','https://curricul.site.nthu.edu.tw/index.php?Lang=en'),('NTHU Library','Study spaces, hours & research','https://www.lib.nthu.edu.tw/en/'),('Campus transport','Shuttle timetables & notices','https://affairs.site.nthu.edu.tw/p/403-1165-1065-1.php?Lang=en'),('Office of Global Affairs','International student resources','https://oga.site.nthu.edu.tw/?Lang=en')])}</div><p class="small">Guide content reviewed: 16 November 2026 · Practical tips are suggestions, not university policy.</p></section>'''
(D/'index.html').write_text(shell('Student Survival Guide',body))
for g in guides:
 body=f'''<article class="article"><a class="back" href="../index.html#guides">← All guides</a><div class="eyebrow">{e(g['category'])} / GUIDE {g['icon']}</div><h1>{e(g['title'])}</h1><p class="intro">{e(g['intro'])}</p><p class="small">Reviewed {g['updated']} · Unofficial student guide</p><div class="article-layout"><div>{''.join(f'<section class="step"><span>{i:02}</span><div><h2>{e(t)}</h2><p>{e(d)}</p></div></section>' for i,(t,d) in enumerate(g['steps'],1))}<aside class="tip"><h2>Small things that help</h2><ul>{''.join(f'<li>{e(t)}</li>' for t in g['tips'])}</ul></aside></div><aside class="article-side"><h2>Your next steps</h2><p class="small">Tick these off as you go. Saved in this browser.</p>{checks(g['checklist'],g['slug'])}<h2>Official resources ↗</h2>{''.join(f'<a class="source" href="{e(url)}" target="_blank" rel="noopener noreferrer">{e(t)} ↗</a>' for t,url in g['sources'])}<p class="small">Check the linked source for current details. Student tips are suggestions, not official requirements.</p></aside></div><a class="button" href="../index.html#guides">Explore another guide →</a></article>'''
 (D/'guides'/f"{g['slug']}.html").write_text(shell(g['short'],body,True))
(D/'assets').mkdir(exist_ok=True)
for file in (P/'assets').glob('*'):shutil.copy(file,D/'assets'/file.name)
if (P/'AGENTS.md').exists():shutil.copy(P/'AGENTS.md',D/'AGENTS.md')
print(f'Built homepage and {len(guides)} guide pages.')
# Use small vector arrows so navigation does not depend on font glyph coverage.
arrow = '<svg class="arrow-icon" aria-hidden="true" viewBox="0 0 16 16"><path d="M3 13 13 3M3 3h10v10" fill="none" stroke="currentColor" stroke-width="1.5"/></svg>'
for page in D.rglob('*.html'):
 page.write_text(page.read_text().replace('↗',arrow))
